        "fact_id": {
          "pattern": "^FACT-[0-9]{3,}$",
          "title": "Fact Id",
          "type": "string"
        },
        "statement": {
          "maxLength": 1000,
          "minLength": 1,
          "title": "Statement",
          "type": "string"
        },
        "block_ids": {
          "items": {
            "type": "string"
          },
          "maxItems": 4,
          "minItems": 1,
